/* Click-to-edit company profile.
 *
 * The page is the real profile layout (generated by profile/build.py) with every editable value
 * tagged with data-path="<json path>". Edits update an in-memory copy of profile/content.json and
 * profile/catalogue.json; "Publish" commits them to GitHub, and the deploy workflow rebuilds the PDF.
 * Sign-in reuses the token from /admin (Sveltia CMS) when available.
 */
(() => {
  "use strict";

  const REPO = "prashants-org/unnatiladders";
  const BRANCH = "main";
  const FILES = { content: "profile/content.json", catalogue: "profile/catalogue.json" };
  const MAX_PHOTO_MB = 5;

  const snapshot = JSON.parse(document.getElementById("snapshot").textContent);
  let original = structuredClone(snapshot); // what is on GitHub (as far as we know)
  const data = structuredClone(snapshot); // working copy
  let pendingPhoto = null; // { file, name }
  let deletedRows = 0; // rows removed since the last publish, for the counter

  // ---------------------------------------------------------------- data helpers
  const fileOf = (path) => (path.startsWith("industries.") ? "catalogue" : "content");
  const keys = (path) => path.split(".").map((k) => (/^\d+$/.test(k) ? Number(k) : k));
  function getPath(path) {
    return keys(path).reduce((o, k) => (o == null ? o : o[k]), data[fileOf(path)]);
  }
  function setPath(path, value) {
    const ks = keys(path);
    let o = data[fileOf(path)];
    ks.slice(0, -1).forEach((k) => (o = o[k]));
    o[ks[ks.length - 1]] = value;
  }
  function originalValue(path) {
    return keys(path).reduce((o, k) => (o == null ? o : o[k]), original[fileOf(path)]);
  }
  const isDirty = () =>
    pendingPhoto || Object.keys(FILES).some((f) => JSON.stringify(data[f]) !== JSON.stringify(original[f]));

  function readField(el) {
    let text = el.innerText.replace(/ /g, " ");
    if (el.dataset.sep !== undefined) {
      return text.split(/\s*[,·]\s*/).map((s) => s.trim()).filter(Boolean);
    }
    text = el.hasAttribute("data-ml") ? text.replace(/\s*\n\s*/g, " ") : text.replace(/\s+/g, " ");
    return text.trim();
  }

  // ---------------------------------------------------------------- UI: toolbar etc.
  const bar = document.createElement("div");
  bar.className = "pe-bar";
  bar.innerHTML = `
    <span class="pe-brand"><img src="/favicon.svg" alt="">Company profile editor</span>
    <span class="pe-hint">Click any <b>highlighted text</b> to edit it. Hover a catalogue row to add or delete rows. Click the founder photo to replace it.</span>
    <label class="pe-toggle"><input type="checkbox" id="pe-show" checked> Show editable areas</label>
    <span class="pe-count" id="pe-count">No changes</span>
    <a class="pe-btn" href="/Unnati-Ladder-Profile.pdf" target="_blank" rel="noopener">Current PDF</a>
    <button class="pe-btn" id="pe-discard" disabled>Discard</button>
    <button class="pe-btn primary" id="pe-publish" disabled>Publish</button>`;
  document.body.prepend(bar);
  document.body.classList.add("pe-show");

  const banner = document.createElement("div");
  banner.className = "pe-banner";
  banner.textContent = "New rows appear in the right place after you publish; the pages are re-laid out automatically.";
  document.body.append(banner);

  const tools = document.createElement("div");
  tools.className = "pe-row-tools";
  tools.innerHTML = `<button data-act="add" title="Add a row below">＋</button><button data-act="del" class="danger" title="Delete this row">✕</button>`;
  document.body.append(tools);

  const photoTip = document.createElement("div");
  photoTip.className = "pe-photo-tip";
  photoTip.textContent = "Click to replace photo";
  photoTip.style.display = "none";
  document.body.append(photoTip);

  const $count = bar.querySelector("#pe-count");
  const $publish = bar.querySelector("#pe-publish");
  const $discard = bar.querySelector("#pe-discard");
  bar.querySelector("#pe-show").addEventListener("change", (ev) => document.body.classList.toggle("pe-show", ev.target.checked));

  function countChanges() {
    const paths = new Set();
    document.querySelectorAll(".ed.changed").forEach((el) => {
      if (!el.closest("tr.pe-new")) paths.add(el.dataset.path);
    });
    return paths.size + document.querySelectorAll("tr.pe-new").length + deletedRows + (pendingPhoto ? 1 : 0);
  }

  function refreshState() {
    const dirty = isDirty();
    const n = Math.max(countChanges(), dirty ? 1 : 0);
    $count.textContent = dirty ? `${n} unsaved change${n === 1 ? "" : "s"}` : "No changes";
    $count.classList.toggle("dirty", !!dirty);
    $publish.disabled = !dirty;
    $discard.disabled = !dirty;
  }

  function toast(msg, ms = 3500) {
    const t = document.createElement("div");
    t.className = "pe-toast";
    t.textContent = msg;
    document.body.append(t);
    setTimeout(() => t.remove(), ms);
  }

  function modal(html, buttons) {
    return new Promise((resolve) => {
      const bg = document.createElement("div");
      bg.className = "pe-modal-bg";
      bg.innerHTML = `<div class="pe-modal">${html}<div class="row"></div></div>`;
      const row = bg.querySelector(".row");
      buttons.forEach(({ label, value, primary }) => {
        const b = document.createElement("button");
        b.className = "pe-btn" + (primary ? " primary" : "");
        b.textContent = label;
        b.onclick = () => {
          const input = bg.querySelector("input");
          bg.remove();
          resolve({ value, input: input ? input.value.trim() : "" });
        };
        row.append(b);
      });
      document.body.append(bg);
      (bg.querySelector("input") || row.lastChild).focus();
    });
  }

  // ---------------------------------------------------------------- fit pages to window
  const pagesEl = document.getElementById("pages");
  function fit() {
    const page = pagesEl.querySelector(".page");
    if (!page) return;
    const z = Math.min(1, (window.innerWidth - 48) / page.offsetWidth);
    pagesEl.style.zoom = z.toFixed(3);
  }
  window.addEventListener("resize", fit);
  fit();

  // ---------------------------------------------------------------- editable text
  function makeEditable(el) {
    el.contentEditable = "plaintext-only";
    if (el.contentEditable !== "plaintext-only") el.contentEditable = "true";
    el.spellcheck = true;
  }
  document.querySelectorAll("[data-path]").forEach(makeEditable);

  document.addEventListener("input", (ev) => {
    const el = ev.target.closest?.("[data-path]");
    if (!el) return;
    const path = el.dataset.path;
    const value = readField(el);
    setPath(path, value);
    // Keep every other place showing the same value in sync (e.g. phone appears 3 times)
    document.querySelectorAll(`[data-path="${CSS.escape(path)}"]`).forEach((other) => {
      if (other === el) return;
      other.textContent = Array.isArray(value) ? value.join(other.dataset.sep || ", ") : value;
    });
    const same = JSON.stringify(value) === JSON.stringify(originalValue(path));
    document.querySelectorAll(`[data-path="${CSS.escape(path)}"]`).forEach((n) => n.classList.toggle("changed", !same));
    if (path.endsWith(".name") && path.startsWith("industries.")) updateIndustryCount(Number(path.split(".")[1]));
    refreshState();
  });

  document.addEventListener("keydown", (ev) => {
    const el = ev.target.closest?.("[data-path]");
    if (!el) return;
    if (ev.key === "Enter" && !el.hasAttribute("data-ml")) {
      ev.preventDefault();
      el.blur();
    }
    if (ev.key === "Escape") el.blur();
  });

  // Paste as plain text (fallback for browsers without plaintext-only)
  document.addEventListener("paste", (ev) => {
    const el = ev.target.closest?.("[data-path]");
    if (!el || el.contentEditable === "plaintext-only") return;
    ev.preventDefault();
    document.execCommand("insertText", false, ev.clipboardData.getData("text/plain"));
  });

  // ---------------------------------------------------------------- catalogue rows
  let hoverRow = null;
  document.addEventListener("mouseover", (ev) => {
    const tr = ev.target.closest?.("tr[data-row]");
    if (tr) {
      hoverRow = tr;
      const r = tr.getBoundingClientRect();
      tools.style.display = "flex";
      tools.style.top = `${Math.max(64, r.top + r.height / 2 - 14)}px`;
      tools.style.left = `${r.right - tools.offsetWidth - 2}px`;
    } else if (!ev.target.closest?.(".pe-row-tools")) {
      tools.style.display = "none";
    }
  });

  function reindex(ind) {
    document.querySelectorAll(`tr[data-ind="${ind}"]`).forEach((tr, j) => {
      tr.dataset.row = `industries.${ind}.rows.${j}`;
      tr.querySelectorAll("[data-path]").forEach((cell) => {
        const field = cell.dataset.path.split(".").pop();
        cell.dataset.path = `industries.${ind}.rows.${j}.${field}`;
      });
    });
    updateIndustryCount(ind);
  }

  function updateIndustryCount(ind) {
    const nameEl = document.querySelector(`[data-path="industries.${ind}.name"]`);
    const countEl = nameEl?.parentElement.querySelector("i");
    if (countEl) countEl.textContent = data.catalogue.industries[ind].rows.length;
  }

  tools.addEventListener("click", async (ev) => {
    const act = ev.target.closest("button")?.dataset.act;
    if (!act || !hoverRow) return;
    const tr = hoverRow;
    const [, ind, , j] = tr.dataset.row.split(".").map((k) => (/^\d+$/.test(k) ? Number(k) : k));
    const rowsArr = data.catalogue.industries[ind].rows;
    if (act === "add") {
      const blank = { brand: "New brand", area: "", fee: "", investment: "", model: "FOFO" };
      rowsArr.splice(j + 1, 0, blank);
      const clone = tr.cloneNode(true);
      clone.classList.add("pe-new");
      clone.querySelectorAll("[data-path]").forEach((cell) => {
        const field = cell.dataset.path.split(".").pop();
        cell.textContent = blank[field];
        cell.classList.add("changed");
        makeEditable(cell);
      });
      tr.after(clone);
      reindex(ind);
      banner.style.display = "block";
      clone.querySelector('[data-path$=".brand"]').focus();
      document.execCommand("selectAll", false, null);
    } else if (act === "del") {
      const name = rowsArr[j].brand || "this row";
      const { value } = await modal(`<h3>Delete “${escapeHtml(name)}”?</h3><p>The row is removed from the catalogue when you publish.</p>`, [
        { label: "Cancel", value: false },
        { label: "Delete row", value: true, primary: true },
      ]);
      if (!value) return;
      rowsArr.splice(j, 1);
      if (!tr.classList.contains("pe-new")) deletedRows++;
      tr.remove();
      reindex(ind);
      banner.style.display = "block";
    }
    tools.style.display = "none";
    refreshState();
  });

  // ---------------------------------------------------------------- founder photo
  const photo = document.querySelector("img[data-img]");
  if (photo) {
    const picker = Object.assign(document.createElement("input"), { type: "file", accept: "image/jpeg,image/png,image/webp" });
    photo.addEventListener("mousemove", (ev) => {
      photoTip.style.display = "block";
      photoTip.style.left = `${ev.clientX + 14}px`;
      photoTip.style.top = `${ev.clientY + 14}px`;
    });
    photo.addEventListener("mouseleave", () => (photoTip.style.display = "none"));
    photo.addEventListener("click", () => picker.click());
    picker.addEventListener("change", () => {
      const file = picker.files[0];
      picker.value = "";
      if (!file) return;
      if (file.size > MAX_PHOTO_MB * 1024 * 1024) return toast(`Please choose a photo under ${MAX_PHOTO_MB} MB.`);
      const ext = (file.name.split(".").pop() || "jpg").toLowerCase().replace("jpeg", "jpg");
      pendingPhoto = { file, name: `founder-${Date.now()}.${ext}` };
      data.content.founder.photo = `/uploads/${pendingPhoto.name}`;
      photo.src = URL.createObjectURL(file);
      refreshState();
    });
  }

  // ---------------------------------------------------------------- discard
  $discard.addEventListener("click", async () => {
    const { value } = await modal("<h3>Discard all changes?</h3><p>This reloads the editor with the current published content.</p>", [
      { label: "Keep editing", value: false },
      { label: "Discard", value: true, primary: true },
    ]);
    if (value) {
      window.onbeforeunload = null;
      location.reload();
    }
  });

  window.onbeforeunload = (ev) => {
    if (isDirty()) {
      ev.preventDefault();
      return "";
    }
  };

  // ---------------------------------------------------------------- GitHub publishing
  const escapeHtml = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

  function bytesToBase64(bytes) {
    let bin = "";
    for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
    return btoa(bin);
  }
  const textToBase64 = (text) => bytesToBase64(new TextEncoder().encode(text));
  const base64ToText = (b64) => new TextDecoder().decode(Uint8Array.from(atob(b64.replace(/\s/g, "")), (c) => c.charCodeAt(0)));

  function storedToken() {
    try {
      const user = JSON.parse(localStorage.getItem("sveltia-cms.user") || "null");
      if (user && user.token) return user.token;
    } catch {}
    return sessionStorage.getItem("ul-pdf-editor.token") || "";
  }

  async function getToken(forcePrompt) {
    let token = forcePrompt ? "" : storedToken();
    if (token) return token;
    const { value, input } = await modal(
      `<h3>Sign in to publish</h3>
       <p>Sign in at <a href="/admin/" target="_blank" rel="noopener">/admin</a> first and then press Publish again, or paste your
       GitHub access token here (the same one you use for the admin).</p>
       <input type="password" placeholder="github_pat_…" autocomplete="off">`,
      [
        { label: "Cancel", value: false },
        { label: "Continue", value: true, primary: true },
      ],
    );
    if (!value || !input) return "";
    sessionStorage.setItem("ul-pdf-editor.token", input);
    return input;
  }

  async function gh(token, path, options = {}) {
    const res = await fetch(`https://api.github.com/repos/${REPO}/${path}`, {
      ...options,
      headers: { Authorization: `Bearer ${token}`, Accept: "application/vnd.github+json", ...(options.headers || {}) },
    });
    if (!res.ok) {
      const body = await res.json().catch(() => ({}));
      const err = new Error(body.message || res.statusText);
      err.status = res.status;
      throw err;
    }
    return res.json();
  }

  const readFileBase64 = (file) =>
    new Promise((resolve, reject) => {
      const r = new FileReader();
      r.onload = () => resolve(String(r.result).split(",")[1]);
      r.onerror = reject;
      r.readAsDataURL(file);
    });

  $publish.addEventListener("click", async () => {
    document.activeElement?.blur?.();
    const changedFiles = Object.keys(FILES).filter((f) => JSON.stringify(data[f]) !== JSON.stringify(original[f]));
    const summary = [
      ...changedFiles.map((f) => (f === "content" ? "Profile text & contact details" : "Franchise catalogue")),
      ...(pendingPhoto ? ["New founder photo"] : []),
    ];
    const { value } = await modal(
      `<h3>Publish changes?</h3><p>This updates:</p><ul>${summary.map((s) => `<li>${s}</li>`).join("")}</ul>
       <p>The new PDF is online about 2 minutes after publishing.</p>`,
      [
        { label: "Cancel", value: false },
        { label: "Publish", value: true, primary: true },
      ],
    );
    if (!value) return;

    let token = await getToken(false);
    if (!token) return;
    $publish.disabled = true;
    $publish.textContent = "Publishing…";
    try {
      // 1. Make sure nobody changed these files since this page was built
      const remote = {};
      for (const f of changedFiles) {
        let cur;
        try {
          cur = await gh(token, `contents/${FILES[f]}?ref=${BRANCH}`);
        } catch (err) {
          if (err.status === 401 || err.status === 403) {
            token = await getToken(true);
            if (!token) throw new Error("Not signed in.");
            cur = await gh(token, `contents/${FILES[f]}?ref=${BRANCH}`);
          } else throw err;
        }
        if (JSON.stringify(JSON.parse(base64ToText(cur.content))) !== JSON.stringify(original[f])) {
          throw Object.assign(new Error("conflict"), { conflict: true });
        }
        remote[f] = cur.sha;
      }
      // 2. Upload the new photo (if any)
      if (pendingPhoto) {
        await gh(token, `contents/public/uploads/${pendingPhoto.name}`, {
          method: "PUT",
          body: JSON.stringify({ message: "PDF editor: upload founder photo", content: await readFileBase64(pendingPhoto.file), branch: BRANCH }),
        });
      }
      // 3. Commit the JSON files
      for (const f of changedFiles) {
        await gh(token, `contents/${FILES[f]}`, {
          method: "PUT",
          body: JSON.stringify({
            message: `PDF editor: update ${f === "content" ? "profile text" : "franchise catalogue"}`,
            content: textToBase64(JSON.stringify(data[f], null, 2)),
            sha: remote[f],
            branch: BRANCH,
          }),
        });
      }
      original = structuredClone(data);
      pendingPhoto = null;
      deletedRows = 0;
      document.querySelectorAll(".changed").forEach((n) => n.classList.remove("changed"));
      document.querySelectorAll(".pe-new").forEach((n) => n.classList.remove("pe-new"));
      banner.style.display = "none";
      await modal(
        `<h3>Published</h3><p>Your changes are saved. The website is rebuilding now, and the updated PDF will be online in about 2 minutes.</p>
         <p><a href="https://github.com/${REPO}/actions" target="_blank" rel="noopener">Watch the progress on GitHub</a></p>`,
        [{ label: "Done", value: true, primary: true }],
      );
    } catch (err) {
      const msg = err.conflict
        ? "The profile was changed elsewhere (in /admin, or a publish is still deploying) after this page was opened. Copy your edits somewhere safe, reload this page in 2–3 minutes and make them again."
        : `Publishing failed: ${escapeHtml(err.message)}. Your edits are still here; please try again.`;
      await modal(`<h3>Couldn't publish</h3><p>${msg}</p>`, [{ label: "OK", value: true, primary: true }]);
    } finally {
      $publish.textContent = "Publish";
      refreshState();
    }
  });

  refreshState();
})();
